int kingHintUnits(const Packet& p,bool large){int tests=0;auto need=[&](bool x,const char* m){tests++;if(!x)throw std::runtime_error(m);};need(kingHintEnabled,"king hint flag");
 auto rawKing=[](const Board& b,int side){for(int i=0;i<90;i++)if(b[i].side!=side&&b[i].type==K)return i;return -1;};
 auto check=[&](Board& b){const Board before=b;for(int side:{0,1}){int enemy=rawKing(b,side),own=kingAt(b,side);for(int f=0;f<90;f++)if(b[f].side==side)for(bool cap:{false,true}){Destinations a;try{a=pseudoDestinations(b,f,cap);}catch(const std::exception& e){std::cerr<<"reference fused generator failed side="<<side<<" from="<<f<<" captures="<<cap<<" reason="<<e.what()<<" cells=";for(int j=0;j<90;j++)if(b[j].live())std::cerr<<j<<":"<<b[j].side<<","<<b[j].type<<","<<b[j].role<<","<<b[j].hidden<<";";std::cerr<<"\n";throw;}auto x=hintDestinations(b,f,cap,enemy);need(std::vector<int>(a.begin(),a.end())==std::vector<int>(x.begin(),x.end()),"hint ordered pseudo differs");}for(bool cap:{false,true})for(bool first:{false,true}){std::vector<Move>a,x,y;legalInto(b,side,cap,first,own,a);legalKingHintInto(b,side,cap,first,own,x);legalKingHintInto(b,side,cap,first,own,y,-1,enemy);need(a==x&&a==y,"hint ordered legal/captures/first differs");need(before==b,"hint changed board");}}};
 if(large){uint32_t seed=9761123;auto next=[&]{return seed=seed*1664525u+1013904223u;};for(int n=0;n<2000;n++){Board b;int kr=n<1000?85:next()%90,kb=n<1000?4:next()%90;if(kr==kb)continue;b[kr]={0,K,K,false};b[kb]={1,K,K,false};for(int j=0;j<24;j++){int at=next()%90;if(b[at].live())continue;int side=next()%2,type=next()%7,role=next()%7;b[at]={side,type,role,next()%3==0};}check(b);}
 for(int side:{0,1})for(int king=0;king<90;king++)for(int other=0;other<90;other++){if(king==other)continue;Board b;b[king]={side,K,K,false};b[other]={1-side,K,K,false};if((king+other)%3==0){int at=(king+other)/2;if(!b[at].live())b[at]={side,P,P,false};}for(bool cap:{false,true}){auto a=pseudoDestinations(b,king,cap),x=hintDestinations(b,king,cap,other);need(std::vector<int>(a.begin(),a.end())==std::vector<int>(x.begin(),x.end()),"hint king geometry/face/capture order differs");}}
 Packet q=p;Board b;b[85]={0,K,K,false};b[4]={1,K,K,false};q.worlds={b};need(safeKingHints(q),"ordinary hint not safe");q.worlds[0][13]={1,K,K,true};need(!safeKingHints(q),"hidden K did not disable");check(q.worlds[0]);q.worlds={b};q.worlds[0][13]={1,K,K,false};need(!safeKingHints(q),"multi K did not disable");check(q.worlds[0]);q.worlds={b};q.worlds[0][13]={-1,K,K,false};need(!safeKingHints(q),"empty raw K did not disable"); /* Legacy fused debug oracle rejects a non-live raw K in capture-only mode; guard-only malformed input test. */q.worlds={b};q.worlds[0][4]=Piece{};need(safeKingHints(q),"captured king hint not safe");check(q.worlds[0]);
 }
 {TTArena arena;TTScope scope(arena);State s=gameState(p.worlds[0],p);const Board before=s.board;const auto key=s.key();for(Move m:legal(s.board,s.turn)){Undo u=push(s,m);for(int side:{0,1}){need(s.kings[side]==kingAt(s.board,side),"hint target cache differs after reveal/capture");std::vector<Move>a,x;legalInto(s.board,side,false,false,s.kings[side],a);legalKingHintInto(s.board,side,false,false,s.kings[side],x,-1,s.kings[side^1]);need(a==x,"cached enemy target differs after make");}pop(s,m,u);need(s.board==before&&s.key()==key,"hint undo differs");for(int side:{0,1})need(s.kings[side]==kingAt(s.board,side),"hint target cache differs after undo");}}
 return tests;}

int lazyLegalityUnits(const Packet& packet,bool large){int tests=0;auto need=[&](bool x,const char* why){tests++;if(!x)throw std::runtime_error(why);};need(lazyLegalityEnabled&&kingHintEnabled,"lazy/hint flags inactive");
 auto board=[&](Board& b){const Board before=b;for(int side:{0,1}){const int king=kingAt(b,side);const bool check=inCheck(b,side,king);for(bool cap:{false,true}){std::vector<Move> old;legalKingHintInto(b,side,cap,false,king,old,check);need(lazyFullLegal(b,side,cap)==old,"lazy full legal sequence differs");std::vector<Move> pseudo;searchPseudos(b,side,cap,-2,pseudo);std::vector<Move> filtered;for(Move m:pseudo)if(legalSearchPseudo(b,side,m,king,check))filtered.push_back(m);need(filtered==old,"pseudo filtering order differs");const Move prefer=pseudo.empty()?Move{}:pseudo.front();auto score=[&](Move m){return m==prefer?10000000:int(m.index()%7)*10;};auto less=[&](Move a,Move b){return score(a)>score(b);};std::stable_sort(old.begin(),old.end(),less);std::stable_sort(pseudo.begin(),pseudo.end(),less);filtered.clear();for(Move m:pseudo)if(legalSearchPseudo(b,side,m,king,check))filtered.push_back(m);need(filtered==old,"frozen stable sort legal-relative order differs");need(b==before,"lazy filter changed Board");}}};
 struct Observation{double value;uint64_t nodes;};auto run=[&](Packet p,int depth,int qleft,double alpha,double beta,bool enabled){struct Restore{bool before;~Restore(){lazyLegalityEnabled=before;}}restore{lazyLegalityEnabled};lazyLegalityEnabled=enabled;TTArena arena;TTScope scope(arena);State state=gameState(p.worlds[0],p);const Board before=state.board;const auto key=state.key();Search s;s.start=std::chrono::steady_clock::now();s.limit=60000;double value=s.search(state,depth,alpha,beta,1,qleft,2);need(state.board==before&&state.key()==key,"lazy search unwind differs");return Observation{value,s.nodes};};
 auto compare=[&](const Packet& p,int depth,int qleft,double alpha,double beta){auto a=run(p,depth,qleft,alpha,beta,false),b=run(p,depth,qleft,alpha,beta,true);need(a.value==b.value,"lazy terminal/q-boundary score differs");need(a.nodes==b.nodes,"lazy changed searched node coverage");};
 if(large){uint32_t seed=971331;auto next=[&]{return seed=seed*1664525u+1013904223u;};for(int n=0;n<1000;n++){Board b;int kr=n<500?85:next()%90,kb=n<500?4:next()%90;if(kr==kb)continue;b[kr]={0,K,K,false};b[kb]={1,K,K,false};for(int j=0;j<24;j++){int at=next()%90;if(b[at].live())continue;b[at]={int(next()%2),int(1+next()%6),int(1+next()%6),next()%3==0};}board(b);}
 for(int kind=0;kind<3;kind++){Board initial;initial[85]={0,K,K,false};initial[4]={1,K,K,false};if(kind<2){initial[49]={0,P,P,false};initial[12]={0,R,R,false};initial[14]={0,R,R,false};if(kind==1)initial[13]={0,P,P,false};need(legal(initial,1).empty(),"terminal fixture has legal move");need(inCheck(initial,1,4)==(kind==1),"terminal check fixture differs");}else{initial[49]={1,R,R,false};initial[76]={0,N,N,false};initial[57]={1,P,P,false};need(!inCheck(initial,0,85),"pinned capture fixture in check");need(legal(initial,0,true).empty()&&!legal(initial,0).empty(),"pinned capture fixture must have only quiet legal moves");}
 for(bool mirrored:{false,true}){Board b;if(mirrored){for(int i=0;i<90;i++)if(initial[i].live()){b[89-i]=initial[i];b[89-i].side^=1;}}else b=initial;board(b);Packet p=packet;p.view=b;p.worlds={b};p.captured.clear();p.turn=(kind<2?1:0)^int(mirrored);p.viewer=p.turn;p.quiet=0;p.gamePly=0;State first=stateOf(b,p.captured,p.turn,p.viewer);p.positions={first.position()};for(int depth:{-6,0,1})for(int qleft:{0,1}){compare(p,depth,qleft,-inf,inf);compare(p,depth,qleft,-200,200);}}}
 }
 for(int depth:{-6,0})for(int qleft:{0,1}){compare(packet,depth,qleft,-inf,inf);compare(packet,depth,qleft,-200,200);}
 {TTArena arena;TTScope scope(arena);State s=gameState(packet.worlds[0],packet);const Board before=s.board;const auto key=s.key();board(s.board);for(Move m:legal(s.board,s.turn)){Undo u=push(s,m);board(s.board);pop(s,m,u);need(s.board==before&&s.key()==key,"lazy reveal/privatecapture/undo differs");}}
 return tests;}

int packedUnits(const Packet& p){int tests=0;auto check=[&](bool b,const char* s){tests++;if(!b)throw std::runtime_error(s);};
 for(int side:{-1,0,1})for(int type=-1;type<=6;type++)for(int role=-1;role<=6;role++)for(bool hidden:{false,true}){Piece a{side,type,role,hidden},b=a;check(int(a.side)==side&&int(a.type)==type&&int(a.role)==role&&a.hidden==hidden,"piece field sign/truncation");check(a==b&&a.live()==(side>=0)&&a.effective()==(hidden?role:type),"piece copy/effective semantics");}
 if(p.depth==19){TTArena arena;TTScope scope(arena);State s=gameState(p.worlds[0],p);auto ms=legal(s.board,s.turn);auto i=std::find(ms.begin(),ms.end(),Move{16,25});check(i!=ms.end(),"old 203 root");const auto key=s.key();Undo u=push(s,*i);const double exact=reference(s,4,-inf,inf,1);Search search;search.start=std::chrono::steady_clock::now();search.limit=30000;const double got=search.search(s,4,-inf,inf,1);check(std::abs(got-exact)<1e-7&&std::abs(-got-203)<1e-7,"packed old203 exact reference");pop(s,*i,u);check(s.key()==key,"packed old203 undo");}
 return tests;
}
